// Un JWT firmado con HMAC-SHA256, armado y verificado a mano. Secreto y datos inventados.
const enc = new TextEncoder();
const b64u = (bytes) => btoa(String.fromCharCode(...new Uint8Array(bytes))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const deb64u = (s) => new TextDecoder().decode(Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/')), (c) => c.charCodeAt(0)));
const clave = await crypto.subtle.importKey('raw', enc.encode('secreto-de-practica-NO-REAL'), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
const firmar = async (texto) => b64u(await crypto.subtle.sign('HMAC', clave, enc.encode(texto)));

const cab = b64u(enc.encode(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
const carga = b64u(enc.encode(JSON.stringify({ sub: 'marta', rol: 'miembro', exp: 1900000000 })));
const token = `${cab}.${carga}.${await firmar(cab + '.' + carga)}`;
console.log('token:', token);
console.log('cabecera:', deb64u(cab));
console.log('carga   :', deb64u(carga), '(cualquiera la puede leer: no está cifrada)');

async function verificar(t) {
  const [c, p, f] = t.split('.');
  // (en un servidor real, la comparación va en tiempo constante)
  return (await firmar(c + '.' + p)) === f ? 'firma válida' : 'FIRMA INVÁLIDA';
}
console.log('\ntal cual            ->', await verificar(token));
// Un atacante cambia el rol en la carga, pero no conoce el secreto y deja la firma vieja.
const cargaFalsa = b64u(enc.encode(JSON.stringify({ sub: 'marta', rol: 'admin', exp: 1900000000 })));
console.log('rol cambiado a admin ->', await verificar(`${cab}.${cargaFalsa}.${token.split('.')[2]}`));
// Si cambia la cabecera a alg:none y borra la firma, un verificador correcto igual exige firma.
const cabNone = b64u(enc.encode(JSON.stringify({ alg: 'none', typ: 'JWT' })));
console.log('alg:none sin firma   ->', await verificar(`${cabNone}.${cargaFalsa}.`));
